import (
	"fmt"
	"testing"
)

type Permission string

const (
	PermOrdersRead   Permission = "orders:read"
	PermOrdersWrite  Permission = "orders:write"
	PermOrdersDelete Permission = "orders:delete"
)

var RolePermissions = map[string][]Permission{
	"user":    {PermOrdersRead},
	"manager": {PermOrdersRead, PermOrdersWrite},
	"admin":   {PermOrdersRead, PermOrdersWrite, PermOrdersDelete},
}

type RBACSubject struct {
	ID    string
	Roles []string
}

func (s *RBACSubject) HasPermission(perm Permission) bool {
	for _, role := range s.Roles {
		for _, p := range RolePermissions[role] {
			if p == perm {
				return true
			}
		}
	}
	return false
}

func TestRBACAccessControl(t *testing.T) {
	regularUser := &RBACSubject{ID: "u-reg", Roles: []string{"user"}}
	managerUser := &RBACSubject{ID: "u-mgr", Roles: []string{"manager"}}

	if !regularUser.HasPermission(PermOrdersRead) {
		t.Fatal("User должен иметь право orders:read")
	}

	if regularUser.HasPermission(PermOrdersWrite) {
		t.Fatal("User НЕ должен иметь право orders:write")
	}

	if !managerUser.HasPermission(PermOrdersWrite) {
		t.Fatal("Manager должен иметь право orders:write")
	}

	if managerUser.HasPermission(PermOrdersDelete) {
		t.Fatal("Manager НЕ должен иметь право orders:delete")
	}

	fmt.Println("Ролевая модель доступа (RBAC) успешно подтверждена:")
	fmt.Printf("  • Пользователь User:    orders:read=%v, orders:write=%v\n",
		regularUser.HasPermission(PermOrdersRead), regularUser.HasPermission(PermOrdersWrite))
	fmt.Printf("  • Менеджер Manager:     orders:write=%v, orders:delete=%v\n",
		managerUser.HasPermission(PermOrdersWrite), managerUser.HasPermission(PermOrdersDelete))
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"sync"
	"testing"
)

type MultiTierRateLimiter struct {
	mu            sync.Mutex
	loginAttempts map[string]int // IP -> count
}

func (l *MultiTierRateLimiter) AllowLogin(ip string) bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	l.loginAttempts[ip]++
	return l.loginAttempts[ip] <= 3 // Лимит: 3 попытки входа
}

func LoginEndpointHandler(limiter *MultiTierRateLimiter) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		clientIP := r.RemoteAddr
		if !limiter.AllowLogin(clientIP) {
			w.Header().Set("Retry-After", "60")
			http.Error(w, "Too many login attempts. Please try again later.", http.StatusTooManyRequests)
			return
		}
		w.WriteHeader(http.StatusOK)
		w.Write([]byte("Login page accessible"))
	}
}

func TestMultiTierRateLimiter(t *testing.T) {
	limiter := &MultiTierRateLimiter{loginAttempts: make(map[string]int)}
	handler := LoginEndpointHandler(limiter)

	clientIP := "203.0.113.195"

	// 3 успешные попытки
	for i := 1; i <= 3; i++ {
		req := httptest.NewRequest(http.MethodPost, "/login", nil)
		req.RemoteAddr = clientIP
		rec := httptest.NewRecorder()
		handler.ServeHTTP(rec, req)
		if rec.Code != http.StatusOK {
			t.Fatalf("Попытка %d должна быть разрешена", i)
		}
	}

	// 4-я попытка (превышение лимита брутфорса)
	req4 := httptest.NewRequest(http.MethodPost, "/login", nil)
	req4.RemoteAddr = clientIP
	rec4 := httptest.NewRecorder()
	handler.ServeHTTP(rec4, req4)

	if rec4.Code != http.StatusTooManyRequests || rec4.Header().Get("Retry-After") != "60" {
		t.Fatalf("Ожидался статус 429: %d", rec4.Code)
	}

	fmt.Println("Многоуровневый Rate Limiter и защита от DDoS подтверждены:")
	fmt.Printf("  • Попытки 1–3: HTTP 200 OK\n")
	fmt.Printf("  • Попытка 4:   HTTP %d Too Many Requests (Retry-After: %s сек)\n",
		rec4.Code, rec4.Header().Get("Retry-After"))
	fmt.Println("  • Эндпоинт аутентификации надежно защищен от брутфорса паролей")
}

