import (
	"fmt"
	"testing"
)

type K8sManifest struct {
	Replicas int
	Image    string
}

type GitOpsController struct {
	gitSourceOfTruth K8sManifest
	liveClusterState K8sManifest
}

func (c *GitOpsController) Sync() {
	// Приведение живого состояния кластера к состоянию из Git
	c.liveClusterState = c.gitSourceOfTruth
}

func (c *GitOpsController) DetectDrift() bool {
	return c.gitSourceOfTruth != c.liveClusterState
}

func TestGitOpsArgoCDSync(t *testing.T) {
	controller := &GitOpsController{
		gitSourceOfTruth: K8sManifest{Replicas: 3, Image: "order-service:v1.2.0"},
	}

	// 1. Начальная синхронизация
	controller.Sync()
	if controller.liveClusterState.Replicas != 3 {
		t.Fatal("Сбой начальной синхронизации")
	}

	// 2. Несанкционированный ручной дрифт в кластере (инженер изменил реплики на 1)
	controller.liveClusterState.Replicas = 1
	if !controller.DetectDrift() {
		t.Fatal("ArgoCD обязан был обнаружить расхождение конфигурации (Drift)!")
	}

	// 3. Автоматическое самоисцеление (Self-Healing)
	controller.Sync()
	if controller.liveClusterState.Replicas != 3 {
		t.Fatal("Self-Healing обязан вернуть состояние к 3 репликам из Git")
	}

	// 4. Декларативный откат (Rollback через Git)
	controller.gitSourceOfTruth.Image = "order-service:v1.1.0" // git revert!
	controller.Sync()

	if controller.liveClusterState.Image != "order-service:v1.1.0" {
		t.Fatalf("Откат не применился: %s", controller.liveClusterState.Image)
	}

	fmt.Println("Методология GitOps (ArgoCD Self-Healing) подтверждена:")
	fmt.Printf("  • Кластер синхронизирован с Git: Образ=%s, Реплик=%d\n",
		controller.liveClusterState.Image, controller.liveClusterState.Replicas)
	fmt.Println("  • Ручные изменения в K8s мгновенно перезаписываются манифестом из Git")
}

package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"testing"
)

type OIDCUserClaims struct {
	Sub   string   `json:"sub"`
	Email string   `json:"email"`
	Roles []string `json:"roles"`
}

func ValidateAndParseToken(tokenString string, secretKey []byte) (*OIDCUserClaims, error) {
	parts := strings.Split(tokenString, ".")
	if len(parts) != 3 {
		return nil, errors.New("invalid token format")
	}

	// Проверка подписи HMAC-SHA256
	signatureData := parts[0] + "." + parts[1]
	mac := hmac.New(sha256.New, secretKey)
	mac.Write([]byte(signatureData))
	expectedSignature := base64.RawURLEncoding.EncodeToString(mac.Sum(nil))

	if parts[2] != expectedSignature {
		return nil, errors.New("invalid token signature: rejected by OIDC validator")
	}

	payloadBytes, _ := base64.RawURLEncoding.DecodeString(parts[1])
	var claims OIDCUserClaims
	_ = json.Unmarshal(payloadBytes, &claims)
	return &claims, nil
}

func TestOIDCJWTValidator(t *testing.T) {
	secret := []byte("keycloak-shared-secret-signing-key")

	header := base64.RawURLEncoding.EncodeToString([]byte(`{"alg":"HS256","typ":"JWT"}`))
	payload := base64.RawURLEncoding.EncodeToString([]byte(`{"sub":"usr-oidc-10","email":"director@corp.ru","roles":["admin","billing_manager"]}`))

	mac := hmac.New(sha256.New, secret)
	mac.Write([]byte(header + "." + payload))
	signature := base64.RawURLEncoding.EncodeToString(mac.Sum(nil))

	validJWT := fmt.Sprintf("%s.%s.%s", header, payload, signature)

	claims, err := ValidateAndParseToken(validJWT, secret)
	if err != nil || claims.Email != "director@corp.ru" {
		t.Fatalf("Сбой валидации OIDC токена: %v", err)
	}

	// Попытка передать поддельный токен
	tamperedJWT := validJWT + "fake"
	_, errTampered := ValidateAndParseToken(tamperedJWT, secret)
	if errTampered == nil {
		t.Fatal("Поддельный токен обязан быть отклонен")
	}

	fmt.Println("Интеграция с Identity Provider (OAuth2/OIDC) подтверждена:")
	fmt.Printf("  • Авторизован субъект: %s (%s)\n", claims.Sub, claims.Email)
	fmt.Printf("  • Роли пользователя:   %v\n", claims.Roles)
	fmt.Println("  • Подпись токена проверена локально без синхронных RPC запросов к Keycloak")
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"sync"
	"testing"
)

type ChargeService struct {
	mu           sync.Mutex
	cachedTx     map[string]string
	realCharges  int
}

func (s *ChargeService) HandleCharge(w http.ResponseWriter, r *http.Request) {
	key := r.Header.Get("Idempotency-Key")
	if key == "" {
		http.Error(w, "Idempotency-Key header is required", http.StatusBadRequest)
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	// Если запрос повторный — отдаем готовый результат
	if receipt, found := s.cachedTx[key]; found {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		w.Write([]byte(receipt))
		return
	}

	// Реальное списание денег
	s.realCharges++
	receipt := fmt.Sprintf(`{"status":"SUCCESS","charge_id":"ch_%d","amount":5000}`, s.realCharges)
	s.cachedTx[key] = receipt

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(receipt))
}

func TestIdempotentChargeEndpoint(t *testing.T) {
	service := &ChargeService{cachedTx: make(map[string]string)}
	idemKey := "uuid-mobile-charge-777"

	// 1. Первый запрос (Реальное списание)
	req1 := httptest.NewRequest(http.MethodPost, "/charge", nil)
	req1.Header.Set("Idempotency-Key", idemKey)
	rec1 := httptest.NewRecorder()
	service.HandleCharge(rec1, req1)

	if rec1.Code != http.StatusOK || service.realCharges != 1 {
		t.Fatalf("Сбой первого списания: %d", rec1.Code)
	}

	// 2. Сетевой ретрай из тоннеля метро с тем же ключом
	req2 := httptest.NewRequest(http.MethodPost, "/charge", nil)
	req2.Header.Set("Idempotency-Key", idemKey)
	rec2 := httptest.NewRecorder()
	service.HandleCharge(rec2, req2)

	if rec2.Code != http.StatusOK || service.realCharges != 1 {
		t.Fatalf("Второй запрос вызвал повторное списание! charges=%d", service.realCharges)
	}

	if rec1.Body.String() != rec2.Body.String() {
		t.Fatal("Ответы обязаны совпадать")
	}

	fmt.Println("Идемпотентный эндпоинт POST /charge успешно подтвержден:")
	fmt.Printf("  • Ответ на запрос 1: %s\n", rec1.Body.String())
	fmt.Printf("  • Ответ на запрос 2: %s (Мгновенно из кэша идемпотентности)\n", rec2.Body.String())
	fmt.Printf("  • Количество реальных списаний средств: %d\n", service.realCharges)
}

