)

type ActiveSagaRecord struct {
	SagaID    string
	Status    string // "IN_PROGRESS", "COMPLETED", "TIMED_OUT_COMPENSATED"
	Deadline  time.Time
}

type DistributedTimeoutWatcher struct {
	sagas map[string]*ActiveSagaRecord
}

func (w *DistributedTimeoutWatcher) ScanAndCompensateTimeouts(now time.Time) []string {
	var timedOutSagas []string
	for _, s := range w.sagas {
		if s.Status == "IN_PROGRESS" && now.After(s.Deadline) {
			s.Status = "TIMED_OUT_COMPENSATED"
			timedOutSagas = append(timedOutSagas, s.SagaID)
		}
	}
	return timedOutSagas
}

func TestSagaTimeoutWatcher(t *testing.T) {
	now := time.Now()

	watcher := &DistributedTimeoutWatcher{
		sagas: map[string]*ActiveSagaRecord{
			// Нормальная сага: дедлайн через 20 секунд
			"saga-active-1": {SagaID: "saga-active-1", Status: "IN_PROGRESS", Deadline: now.Add(20 * time.Second)},
			// Зависшая сага: склад молчит уже 45 секунд (дедлайн был 15 сек назад)
			"saga-stuck-99": {SagaID: "saga-stuck-99", Status: "IN_PROGRESS", Deadline: now.Add(-15 * time.Second)},
		},
	}

	compensated := watcher.ScanAndCompensateTimeouts(now)

	if len(compensated) != 1 || compensated[0] != "saga-stuck-99" {
		t.Fatalf("Ожидался откат зависшей саги: %v", compensated)
	}

	if watcher.sagas["saga-stuck-99"].Status != "TIMED_OUT_COMPENSATED" {
		t.Fatal("Статус саги обязан смениться на TIMED_OUT_COMPENSATED")
	}

	fmt.Println("Отказоустойчивая хореография (Saga Timeout Watcher) подтверждена:")
	fmt.Printf("  • Обнаружена зависшая сага: %v\n", compensated)
	fmt.Printf("  • Статус переведен в: %s\n", watcher.sagas["saga-stuck-99"].Status)
	fmt.Println("  • Запущен компенсирующий откат списания денег, зависание заказа предотвращено")
}

package main

import (
	"errors"
	"fmt"
	"sync"
	"testing"
	"time"
)

type CBMode int

const (
	ModeClosed CBMode = iota
	ModeOpen
	ModeHalfOpen
)

type StrictCircuitBreaker struct {
	mu          sync.Mutex
	mode        CBMode
	failCount   int
	cooldownEnd time.Time
}

func (cb *StrictCircuitBreaker) Execute(action func() error) (string, error) {
	cb.mu.Lock()
	now := time.Now()

	if cb.mode == ModeOpen {
		if now.After(cb.cooldownEnd) {
			cb.mode = ModeHalfOpen // Время отдыха истекло -> пускаем 1 пробный вызов
		} else {
			cb.mu.Unlock()
			return "FALLBACK_STATIC_DATA", nil // Мгновенный ответ без сети!
		}
	}
	cb.mu.Unlock()

	err := action()

	cb.mu.Lock()
	defer cb.mu.Unlock()

	if err != nil {
		cb.failCount++
		if cb.failCount >= 3 || cb.mode == ModeHalfOpen {
			cb.mode = ModeOpen
			cb.cooldownEnd = time.Now().Add(50 * time.Millisecond) // короткий таймаут для теста
		}
		return "", err
	}

	// Успешный вызов
	cb.failCount = 0
	cb.mode = ModeClosed
	return "REMOTE_SERVICE_SUCCESS", nil
}

func TestStrictCircuitBreaker(t *testing.T) {
	cb := &StrictCircuitBreaker{}
	failingCall := func() error { return errors.New("500 downstream internal error") }
	okCall := func() error { return nil }

	// 3 сбоя подряд -> цепь размыкается
	for i := 0; i < 3; i++ {
		_, _ = cb.Execute(failingCall)
	}

	if cb.mode != ModeOpen {
		t.Fatal("Цепь должна была перейти в режим ModeOpen")
	}

	// Вызов в режиме Open -> мгновенный Fallback
	resFallback, _ := cb.Execute(failingCall)
	if resFallback != "FALLBACK_STATIC_DATA" {
		t.Fatalf("Ожидался Fallback ответ: %s", resFallback)
	}

	// Ждем окончания периода отдыха -> переход в Half-Open и успешный вызов
	time.Sleep(60 * time.Millisecond)
	resRecovered, _ := cb.Execute(okCall)

	if cb.mode != ModeClosed || resRecovered != "REMOTE_SERVICE_SUCCESS" {
		t.Fatalf("Цепь обязана вернуться в ModeClosed: mode=%d, res=%s", cb.mode, resRecovered)
	}

	fmt.Println("Паттерн выключателя (Strict Circuit Breaker) успешно подтвержден:")
	fmt.Printf("  • Режим Open:      %s (Мгновенно из Fallback)\n", resFallback)
	fmt.Printf("  • Пробный вызов:   %s (Восстановление в Closed)\n", resRecovered)
	fmt.Println("  • Защитный автомат изолирует сбои и плавно восстанавливает нормальную работу")
}

